// What the site knows, and the shape of the files it reads.
//
// `catalog.json`, `content/<project>/<version>.json` and `search.json` are generated by `scripts/` and are the only inputs
// this app has: no API, no database, and no knowledge of the tool that produced them.

export interface Section {
	id: string;
	title: string;
	description: string;
}

export interface PageEntry {
	/** The address of the page inside its version: `index`, `ports`, or `index.html` for an imported page. */
	href: string;
	title: string;
	/** Authored here as Markdown, or written by a project's own build. */
	kind: 'md' | 'build';
	description?: string;
	/** Repo-relative path of what a pencil should open, when the page has one. */
	source?: string;
	/** An explicit edit address from front matter, for a page that lives outside this repository. */
	edit?: string;
	/** When the page last changed, ISO. */
	updated?: string;
	/** Reading time, in whole minutes, counted at 200 words a minute. */
	minutes?: number;
}

export interface Version {
	version: string;
	/** When the newest page of this version was written or imported, ISO. */
	builtAt?: string;
	pages: PageEntry[];
}

export interface Project {
	id: string;
	title: string;
	section: string;
	summary: string;
	/** The newest version, by number. */
	latest: string;
	versions: Version[];
	/** A project that lives in its own repository overrides where the pencil points. */
	repository?: string;
	editBranch?: string;
}

export interface Catalog {
	generated: string;
	sections: Section[];
	projects: Project[];
	/** Where "Edit this page" points unless a project says otherwise. */
	repository?: string;
	editBranch?: string;
	/** The published site, used to build permalinks that survive being pasted into an issue. */
	siteUrl?: string;
	/** The suggestions shown under the home page's search field, from `content/config.json`. */
	hints?: string[];
}

export interface Heading {
	id: string;
	text: string;
	level: number;
}

export interface CompiledPage {
	title: string;
	description?: string;
	html: string;
	headings: Heading[];
}

export interface BodyFile {
	pages: Record<string, CompiledPage>;
}

export interface SearchRecord {
	t: string;
	p: string;
	pn: string;
	v: string;
	s: string;
	u: string;
	/** Heading text, for matching and for "In this article" hints. */
	h: string[];
	/** Heading ids, parallel to `h`, so a result can land on a section rather than a page. */
	ha: string[];
	x: string;
}

export interface SearchIndex {
	generated: string;
	pages: SearchRecord[];
}
